import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_metadata(metadata_str):
    """Remove potentially dangerous characters from metadata fields."""
    # Basic sanitization - strip null bytes and control chars
    cleaned = metadata_str.replace('\x00', '').strip()
    # Limit length to prevent buffer issues
    return cleaned[:256]

@app.route('/api/v2/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 415

    output_format = request.form.get('format', 'pdf')
    author_meta = request.form.get('author', 'Unknown')
    title_meta = request.form.get('title', 'Untitled')

    # Sanitize metadata inputs
    author_meta = sanitize_metadata(author_meta)
    title_meta = sanitize_metadata(title_meta)

    # Generate unique job ID
    job_id = hashlib.sha256(f"{file.filename}{time.time()}".encode()).hexdigest()[:16]

    input_path = os.path.join(UPLOAD_DIR, f"{job_id}_{secure_filename(file.filename)}")
    output_path = os.path.join(UPLOAD_DIR, f"{job_id}_output.{output_format}")

    file.save(input_path)

    try:
        # Build conversion command using LibreOffice
        # The output format is validated against a known list
        valid_formats = ['pdf', 'docx', 'odt', 'html', 'txt', 'rtf']
        if output_format not in valid_formats:
            return jsonify({'error': 'Invalid output format'}), 400

        # Construct the conversion command
        # Using --infilter to specify handling and custom output naming
        cmd = f"libreoffice --headless --convert-to {output_format} --outdir {UPLOAD_DIR} {input_path}"

        # Apply metadata post-conversion using exiftool if PDF
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=60,
                              cwd=UPLOAD_DIR)

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'details': result.stderr.decode()[:200]}), 500

        # LibreOffice names output based on input filename
        lo_output = os.path.join(UPLOAD_DIR, 
            f"{job_id}_{secure_filename(file.filename).rsplit('.', 1)[0]}.{output_format}")

        if output_format == 'pdf' and (author_meta != 'Unknown' or title_meta != 'Untitled'):
            # Set PDF metadata using exiftool
            meta_cmd = f'exiftool -Author="{author_meta}" -Title="{title_meta}" "{lo_output}"'
            subprocess.run(meta_cmd, shell=True, capture_output=True, timeout=10)

        if os.path.exists(lo_output):
            return send_file(lo_output, as_attachment=True,
                           download_name=f"converted.{output_format}")
        else:
            return jsonify({'error': 'Output file not found'}), 500

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup
        for f in [input_path]:
            if os.path.exists(f):
                try:
                    os.remove(f)
                except OSError:
                    pass

@app.route('/api/v2/formats', methods=['GET'])
def list_formats():
    return jsonify({
        'input': list(ALLOWED_EXTENSIONS),
        'output': ['pdf', 'docx', 'odt', 'html', 'txt', 'rtf']
    })

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
